-- Migration: shorten all timed_text cues > 75 chars across Days 15-30.
-- Targets <=75 chars per cue (~3 lines max at 25 chars/line on mobile).
-- start_s values unchanged. Coach voice kept verbatim where possible.

begin;

-- Day 15: The Anchor Check (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 267,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_15/lesson_15_seg_01.mp3"],"total_audio_seconds":87.28,"timed_text":[{"start_s":0.0,"text":"Day 15. Your focus anchor — the word your mind returns to when it drifts."},{"start_s":9.34,"text":"The most powerful anchor isn''t just a word in your head — it''s physical."},{"start_s":22.7,"text":"Elite athletes do this instinctively. They''re trained focus triggers."},{"start_s":47.86,"text":"The key is consistency — the same thing, the same way, every single time."},{"start_s":57.26,"text":"Do it enough times in a focused state and it begins to trigger the state."},{"start_s":66.68,"text":"That''s what we''re building today."},{"start_s":69.08,"text":"Think about the physical environment where you compete."},{"start_s":72.46,"text":"What is something you can see, touch, feel or do?"},{"start_s":77.12,"text":"Something always available in that space — that''s your competition anchor."},{"start_s":83.52,"text":"On your screen, you''re going to identify it and lock it in."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Think about the physical space where you compete. What do you see, hear, or feel in that environment that is always there — every competition, every time?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Identify your physical anchor — something in that space, or something you wear or carry, that you can use as a consistent focus trigger. Something you can touch, see, or do deliberately before or during competition.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Design the moment — exactly when in competition will you use this anchor? Between plays? Before the starting signal? After a mistake? Write the specific moment and the exact action.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Say your focus word once. Feel your attention settle. That word plus that physical anchor — those two together are your return to center.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_15/lesson_15_seg_02.mp3"],"total_audio_seconds":20.14,"timed_text":[{"start_s":0.0,"text":"Every rep with that anchor strengthens the link to your focused state."},{"start_s":6.62,"text":"Do it in practice, do it in warmups, do it in competition."},{"start_s":11.12,"text":"The more consistent you are, the faster it works when the pressure is real."},{"start_s":16.26,"text":"Check out the journal and have to finish."},{"start_s":17.96,"text":"Day 15 is complete."}]},{"type":"journal_prompt","prompt":"What physical anchor did you choose — and why does that specific thing feel right for your competition environment?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000015';

-- Day 16: The Traffic Light System (1 cue(s) shortened)
update public.lessons set
  duration_seconds = 259,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_16/lesson_16_seg_01.mp3"],"total_audio_seconds":82.76,"timed_text":[{"start_s":0.0,"text":"Day 16. One of the most practical tools in sports psychology."},{"start_s":9.58,"text":"He calls it the traffic light system, green amber red."},{"start_s":15.3,"text":"Green is where you want to compete, relaxed in the flow."},{"start_s":20.54,"text":"System one is running the show."},{"start_s":22.54,"text":"You''re executing without overthinking."},{"start_s":25.5,"text":"Your body trusts your training."},{"start_s":26.86,"text":"This is what flow state looks like."},{"start_s":30.18,"text":"Amber or yellow is the warning state."},{"start_s":33.16,"text":"Fatigue, frustration, pressure — your focus is starting to drift."},{"start_s":39.16,"text":"You''re not in the red yet, but you''re heading there."},{"start_s":42.1,"text":"So yellow or amber is where the tools matter most."},{"start_s":45.46,"text":"Catch yourself here — you can course correct before the spiral."},{"start_s":51.0,"text":"Bed is where performance goes to die."},{"start_s":53.38,"text":"Dominated by negative self-talk, poor decisions, emotional reactions."},{"start_s":60.8,"text":"Once you''re in the red, it takes real effort to come back."},{"start_s":65.98,"text":"Most athletes don''t know where they are."},{"start_s":67.9,"text":"They just feel bad and can''t explain why."},{"start_s":70.9,"text":"The traffic light: a language for your state and a plan for each."},{"start_s":76.72,"text":"On screen — define what each state looks and feels like for you."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe what GREEN feels like for you in competition — physically, mentally, emotionally. What are the specific signs that you are in your optimal performance state?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Describe AMBER — the warning signs that tell you your state is slipping. What do you notice first? Is it physical tension, a specific thought, a change in your breathing?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Describe RED — what it looks and feels like when you''ve lost the mental battle. What are the unmistakable signs for you specifically?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"For AMBER only — when you notice those warning signs, what is your first move? Which tool do you use to bring yourself back before you hit red?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_16/lesson_16_seg_02.mp3"],"total_audio_seconds":16.72,"timed_text":[{"start_s":0.0,"text":"The goal isn''t always to be in the green."},{"start_s":3.28,"text":"That''s just not realistic."},{"start_s":5.42,"text":"The goal: recognize amber before it becomes red, and have a tool ready."},{"start_s":12.62,"text":"Check out the journal and after you finish, Day 16 is complete."}]},{"type":"journal_prompt","prompt":"In your last competition, were you mostly green, amber, or red? At what point did your state shift — and what caused it?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000016';

-- Day 17: First Things First (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 241,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_17/lesson_17_seg_01.mp3"],"total_audio_seconds":92.87,"timed_text":[{"start_s":0.0,"text":"Day 17. Before we go deeper, I need to ask you something."},{"start_s":6.78,"text":"Why are you doing this?"},{"start_s":8.96,"text":"Not the athletic goals. Not the starting spot, stats, or scholarship."},{"start_s":14.88,"text":"I mean the bigger picture."},{"start_s":16.82,"text":"What are the things in your life that matter most?"},{"start_s":19.56,"text":"The people, the relationships, the responsibilities it''s supposed to serve."},{"start_s":25.56,"text":"Bill Bessick calls this, keeping the first things first."},{"start_s":29.9,"text":"Those who burn out have lost their connection to their why."},{"start_s":43.18,"text":"When sport becomes the only thing, it becomes the wrong thing."},{"start_s":48.16,"text":"Because sport is not the point."},{"start_s":50.9,"text":"Sport is just the vehicle."},{"start_s":52.68,"text":"The relationships, the character, the future it creates — that''s the point."},{"start_s":59.86,"text":"Family, friends, health, academics — the people counting on you."},{"start_s":70.36,"text":"Compete for something bigger than the scoreboard — you''re tougher to break."},{"start_s":81.02,"text":"On your screen, you''re going to name your first things."},{"start_s":85.04,"text":"On your screen — name your first things. The ones that matter most."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Family — Who are the people in your family that your athletic journey is connected to? Why does competing well matter when you think about them?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Friends and teammates — Who in your life shows up for you regardless of performance? Why do those relationships matter to how you compete?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Health — Your body is the vehicle. What does taking care of it mean to you beyond sport — for the life you''re building after the final game?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Academics and future — What are you building outside the lines? Why does the person you''re becoming in the classroom and in the real world matter?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Now — write one sentence: ''I compete because...'' Let it be honest. Let it be bigger than wins and losses.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_17/lesson_17_seg_02.mp3"],"total_audio_seconds":23.82,"timed_text":[{"start_s":0.0,"text":"That why is now saved in your profile."},{"start_s":4.3,"text":"Read it when competition stops feeling worth it."},{"start_s":7.58,"text":"Read it when the training is hard and the results aren''t showing up yet."},{"start_s":11.54,"text":"The athletes who last never lose their connection to that answer."},{"start_s":20.72,"text":"After you finish, day 17 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000017';

-- Day 18: The If-Then Plan (2 cue(s) shortened)
update public.lessons set
  duration_seconds = 161,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_18/lesson_18_seg_01.mp3"],"total_audio_seconds":70.27,"timed_text":[{"start_s":0.0,"text":"A -18."},{"start_s":1.56,"text":"The biggest reason athletes break: they''ve never planned for the worst."},{"start_s":7.46,"text":"Not the success, the worst case."},{"start_s":10.82,"text":"What happens if you fall behind early?"},{"start_s":13.2,"text":"What if you make a visible error in front of the biggest crowd ever?"},{"start_s":18.1,"text":"What if your body gives out before the competition is over?"},{"start_s":22.52,"text":"Most athletes avoid those questions."},{"start_s":24.86,"text":"They think planning for failure invites it."},{"start_s":27.78,"text":"That''s backwards."},{"start_s":28.96,"text":"Planning for adversity makes you dangerous — response ready in advance."},{"start_s":35.48,"text":"This is the then plan."},{"start_s":37.48,"text":"If X happens, then I do Y."},{"start_s":40.66,"text":"It''s not pessimism, it''s preparation."},{"start_s":44.48,"text":"Research is clear on this."},{"start_s":46.56,"text":"Pre-planning adversity: you recover faster and perform more consistently."},{"start_s":56.56,"text":"You''re not hoping the bad thing doesn''t happen."},{"start_s":59.48,"text":"You''re deciding in advance that it doesn''t own you."},{"start_s":62.48,"text":"On screen — build your If-Then plan for three likely adversity scenarios."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"What is the most likely thing to go wrong in your next competition — the one that typically starts your mental spiral? Describe the scenario and write your exact response: breath, reset word, refocus.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Second most likely adversity scenario — and your response.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Third scenario — and your response.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_18/lesson_18_seg_02.mp3"],"total_audio_seconds":16.69,"timed_text":[{"start_s":0.0,"text":"You just made three decisions in advance."},{"start_s":3.7,"text":"When those moments arrive and they will, your brain already has the answer."},{"start_s":9.18,"text":"No freeze, no spiral, just a plan."},{"start_s":13.56,"text":"Now that you''re finished, day 18 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000018';

-- Day 19: Reframe — When Your Mind Broke (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 171,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_19/lesson_19_seg_01.mp3"],"total_audio_seconds":80.9,"timed_text":[{"start_s":0.0,"text":"A19, today we do something different."},{"start_s":3.56,"text":"There''s a moment in your career where your mind completely broke on you."},{"start_s":9.74,"text":"Your focus left, the spiral started."},{"start_s":12.92,"text":"You couldn''t come back, and the performance suffered because of it."},{"start_s":17.3,"text":"You''ve probably replayed that moment as a failure."},{"start_s":21.06,"text":"What if you replayed it as a training opportunity instead?"},{"start_s":24.54,"text":"You cannot achieve greatness without mistakes."},{"start_s":27.76,"text":"The question isn''t whether you make errors."},{"start_s":30.66,"text":"Bill Bezak puts it this way."},{"start_s":32.72,"text":"You cannot achieve greatness without mistakes."},{"start_s":35.46,"text":"The question isn''t whether you make errors."},{"start_s":37.9,"text":"Accept the mistakes, learn from them, and refuse to let them define you."},{"start_s":44.06,"text":"That''s what we''re doing today."},{"start_s":46.52,"text":"Retrospective reframing."},{"start_s":48.32,"text":"Not pretending that bad moments didn''t happen."},{"start_s":51.6,"text":"Updating your brain''s response to it with the tools you now have."},{"start_s":55.44,"text":"Every time you do this, that memory loses a little more of its charge."},{"start_s":60.56,"text":"Your brain will look for the trained response — not the old pattern."},{"start_s":66.42,"text":"Not the old panic pattern."},{"start_s":68.98,"text":"Think of a specific moment."},{"start_s":71.84,"text":"One that still has some weight to it."},{"start_s":74.42,"text":"This caused you a lot of pain, a lot of anguish."},{"start_s":77.48,"text":"Now, next on your screen, you''re going to walk right through it."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the moment — the situation, what happened, what your mind did, and how it affected your performance.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"At what exact point did the spiral begin? What was the first thought that started the chain?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"With the tools you have now — your reset word, your reset protocol, your focus anchor, your If-Then plan — what would you have done differently? Walk through it step by step.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_19/lesson_19_seg_02.mp3"],"total_audio_seconds":15.46,"timed_text":[{"start_s":0.0,"text":"That moment just became a rep."},{"start_s":2.94,"text":"The next time something like that arrives, your brain has a response."},{"start_s":8.56,"text":"You''ve been there."},{"start_s":10.02,"text":"And now you come out the other side."},{"start_s":12.46,"text":"Now that you''re finished, day 19 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000019';

-- Day 20: Embracing the Suffer (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 233,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_20/lesson_20_seg_01.mp3"],"total_audio_seconds":84.66,"timed_text":[{"start_s":0.0,"text":"Day 20."},{"start_s":2.38,"text":"The question the best coaches ask every athlete they work with."},{"start_s":8.52,"text":"How much are you willing to not tolerate, suffer?"},{"start_s":12.12,"text":"The discomfort, the exhaustion, the psychological pain of being doubted."},{"start_s":25.84,"text":"High achievement inherently involves discomfort."},{"start_s":29.92,"text":"That''s not a side effect of greatness."},{"start_s":32.72,"text":"It''s the price of admission."},{"start_s":34.64,"text":"Here''s what acceptance means in the context of sport."},{"start_s":38.16,"text":"It doesn''t mean you like the hard parts."},{"start_s":40.4,"text":"It means you stop treating the hard parts as signals to stop."},{"start_s":44.04,"text":"You accept they''re present — fatigue, doubt, fear — and compete with them."},{"start_s":53.06,"text":"They don''t go away."},{"start_s":53.8,"text":"Champions aren''t the ones who stopped feeling the pressure."},{"start_s":59.24,"text":"They''re the ones who kept moving through it."},{"start_s":61.62,"text":"Face that question directly — not to inspire you, to prepare you."},{"start_s":67.62,"text":"The athlete who chose the suffering handles it completely differently."},{"start_s":80.16,"text":"On your screen, you''re going to answer three core questions, honestly."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"What do you want? Not what you''re supposed to want — what do you actually want from your athletic career? Be honest and specific.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"How badly do you want it? What is the evidence in your daily behavior that you want it at that level? Not intentions — actual actions.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"How much will you suffer for it? What are you willing to go through — physically, mentally, emotionally — to get to where you''re trying to go?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_20/lesson_20_seg_02.mp3"],"total_audio_seconds":13.35,"timed_text":[{"start_s":0.0,"text":"Those three answers are your contract with yourself."},{"start_s":8.98,"text":"Check out the next journal and after you finish, day 20 is complete."}]},{"type":"journal_prompt","prompt":"Where is the gap between what you say you want and how you''re actually training for it? What does closing that gap require?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000020';

-- Day 21: The Fighter Mindset (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 167,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_21/lesson_21_seg_01.mp3"],"total_audio_seconds":92.32,"timed_text":[{"start_s":0.0,"text":"Day 21. When you face a challenge, your brain does something automatic."},{"start_s":12.42,"text":"It imagines the worst case — failure, loss, the fear scenario."},{"start_s":19.8,"text":"That''s not weakness."},{"start_s":21.34,"text":"That''s your nervous system doing exactly what it was designed to do."},{"start_s":24.74,"text":"That threat response is ancient."},{"start_s":28.56,"text":"It was built to keep you alive."},{"start_s":30.74,"text":"It fires the same way — facing a predator or stepping to the starting line."},{"start_s":37.3,"text":"There are two types of athletes in those moments."},{"start_s":41.12,"text":"The victim and the fighter."},{"start_s":43.26,"text":"The victim acknowledges the fear and becomes it."},{"start_s":46.82,"text":"They make excuses."},{"start_s":49.0,"text":"They shrink."},{"start_s":50.36,"text":"They find reasons why the situation is unfair or why they''re not ready."},{"start_s":55.0,"text":"And they stay on the safe side of the line."},{"start_s":57.6,"text":"The fighter acknowledges the same fear and steps over the line anyway."},{"start_s":63.5,"text":"They''ve decided the fear doesn''t get to make the call."},{"start_s":69.46,"text":"The difference isn''t talent."},{"start_s":71.46,"text":"It isn''t physical preparation."},{"start_s":74.28,"text":"A decision made in seconds: who''s in charge — you or the fear?"},{"start_s":79.58,"text":"You or the fear?"},{"start_s":80.92,"text":"You''ve been building the tools to make that decision automatically."},{"start_s":84.76,"text":"Today we name it explicitly."},{"start_s":86.82,"text":"On screen — identify your line and declare which side you choose."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the fear you feel before your most challenging competitive moments. Be specific — what does it say? What worst-case scenario does your brain go to?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Now name it for what it is — your brain trying to protect you. It''s not the truth. It''s a signal.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"The fighter steps over the line anyway. What does stepping over the line look like for you — specifically, in the moment that fear arrives?","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000021';

-- Day 22: Visualization — See the Outcome (1 cue(s) shortened)
update public.lessons set
  duration_seconds = 280,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_22/lesson_22_seg_01.mp3"],"total_audio_seconds":59.61,"timed_text":[{"start_s":0.0,"text":"Today: visualization. One of the highest-leverage tools in this program."},{"start_s":8.66,"text":"Mental imagery activates the same neural pathways as physical execution."},{"start_s":16.92,"text":"Your brain can''t distinguish a vivid visualization from the real thing."},{"start_s":23.78,"text":"Every visualization rep is a real training rep."},{"start_s":27.34,"text":"I build custom visualization scripts for every athlete I coach one-on-one."},{"start_s":36.98,"text":"We start with outcome visualization."},{"start_s":39.0,"text":"You need to see yourself succeeding before you can execute the process."},{"start_s":45.86,"text":"Sights, sounds, sensations — the more sensory detail, the more powerful."},{"start_s":53.68,"text":"Start with one breath — then close your eyes and build the scene."}]},{"type":"timed_exercise","duration_seconds":16,"interactive_model":"box_breathing","visual_cues":["One full cycle. Settle in.","Follow the circle."],"steps":[{"text":"Inhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"},{"text":"Exhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Close your eyes. Place yourself in your next competition. Build every detail of the environment.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What do you hear? The crowd, your teammates, the sounds specific to your sport.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Feel your body. What does it feel like to be moving well? What does that sensation feel like?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"See the moment — the execution, the result. Watch yourself succeed. Hold it.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"How does it feel when it happens? Stay there.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_22/lesson_22_seg_02.mp3"],"total_audio_seconds":19.7,"timed_text":[{"start_s":0.0,"text":"Your brain just treated that as a real performance rep."},{"start_s":3.64,"text":"Do this before every competition."},{"start_s":6.3,"text":"Build the image until it feels familiar."},{"start_s":8.86,"text":"Because when it''s familiar, it''s less threatening."},{"start_s":12.32,"text":"And when it''s less threatening, you compete free."},{"start_s":16.48,"text":"Hit the journal and after you finish, day 22 is complete."}]},{"type":"journal_prompt","prompt":"How vivid was the visualization? What detail made it feel most real — and what was hardest to hold?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000022';

-- Day 23: Your Visualization Board (1 cue(s) shortened)
update public.lessons set
  duration_seconds = 215,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_23/lesson_23_seg_01.mp3"],"total_audio_seconds":76.98,"timed_text":[{"start_s":0.0,"text":"Day 23. Commitment: directing your behavior toward your values, every day."},{"start_s":9.82,"text":"The most powerful way to stay anchored to your values: make them visible."},{"start_s":16.42,"text":"Build a picture of the athlete you''re becoming — see it every day."},{"start_s":23.72,"text":"Repeated exposure to a desired image changes what the brain prioritizes."},{"start_s":38.18,"text":"Your attention starts to organize around what you see consistently."},{"start_s":43.14,"text":"What you see consistently, you move toward."},{"start_s":46.4,"text":"This only works if it''s real — specific goals, your why, your identity."},{"start_s":59.24,"text":"Use Canva, use images, use words — build something that pulls you."},{"start_s":71.32,"text":"On your screen, you''ll find the visualization board tool."},{"start_s":75.74,"text":"Take your time."}]},{"type":"visualization_board","ambient_audio":"ambient/ambient_music.mp3","prompt":"Build a picture of the athlete you''re committing to becoming. Your goals. Your why. Your future. Make it specific enough that looking at it every day means something.","pull_from_profile":["identity_statement","core_why"],"save_to_profile":true},{"type":"voiceover","audio_files":["lesson_23/lesson_23_seg_02.mp3"],"total_audio_seconds":18.18,"timed_text":[{"start_s":0.0,"text":"That board lives on your home screen now."},{"start_s":2.92,"text":"Look at it every morning before you train."},{"start_s":5.34,"text":"Look at it the night before competition."},{"start_s":7.32,"text":"Look at it when the work gets hard and the results aren''t showing up yet."},{"start_s":11.48,"text":"That''s not decoration."},{"start_s":13.34,"text":"That''s a commitment device."},{"start_s":15.7,"text":"After you finish, day 23 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000023';

-- Day 24: Raise Your Bottom Line (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 231,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_24/lesson_24_seg_01.mp3"],"total_audio_seconds":86.1,"timed_text":[{"start_s":0.0,"text":"Day 24,"},{"start_s":2.06,"text":"Most athletes aim for perfection."},{"start_s":4.64,"text":"Perfection is one of the most damaging standards to chase."},{"start_s":18.28,"text":"Here''s a better target."},{"start_s":19.88,"text":"Raise your bottom line."},{"start_s":22.88,"text":"Here''s what that means."},{"start_s":24.44,"text":"Every athlete has a range."},{"start_s":26.72,"text":"Their best days and their worst days."},{"start_s":29.54,"text":"The question isn''t how high your ceiling is."},{"start_s":32.4,"text":"The question is, how high is your floor?"},{"start_s":36.7,"text":"If your worst performance is at 60% of capability — that''s your floor."},{"start_s":44.44,"text":"Athletes who compound commit to fundamentals until their floor rises."},{"start_s":56.0,"text":"Not their ceiling, their floor."},{"start_s":58.54,"text":"Their worst days become 75%, then 10, 85%."},{"start_s":63.96,"text":"Compounding happens through daily behaviors, not heroic game day efforts."},{"start_s":70.86,"text":"The routine, the evidence log, the reps you build when nobody''s watching."},{"start_s":76.84,"text":"The commitment isn''t to be perfect, it''s to be reliable."},{"start_s":81.58,"text":"On screen — look at your current floor and commit to raising it."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Honestly — what does your worst competitive performance look like right now? Not your fear of what it could be. What does it actually look like on a bad day?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What are the specific daily behaviors that, if you did them consistently, would raise that floor? Not the big things — the small, repeatable ones.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Commit to one behavior from that list that you will do every single day for the rest of this program — not because you feel like it, but because that''s how the floor rises.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_24/lesson_24_seg_02.mp3"],"total_audio_seconds":10.74,"timed_text":[{"start_s":0.0,"text":"Commit to your worst day being good enough."},{"start_s":2.96,"text":"Because when your floor is solid, your ceiling takes care of itself."},{"start_s":7.14,"text":"Go hit the journal and when you finish, day 24 is complete."}]},{"type":"journal_prompt","prompt":"What would change about how you compete if you stopped chasing your best day and started committing to your most reliable day?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000024';

-- Day 25: The Mistake Protocol (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 229,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_25/lesson_25_seg_01.mp3"],"total_audio_seconds":65.55,"timed_text":[{"start_s":0.0,"text":"Day 25."},{"start_s":2.1,"text":"The five seconds after a mistake matter more than the mistake itself."},{"start_s":9.22,"text":"Here''s the pattern."},{"start_s":11.28,"text":"Athlete makes error."},{"start_s":13.34,"text":"Brain fires immediately."},{"start_s":15.44,"text":"Replays the mistake."},{"start_s":17.76,"text":"Catastrophizes the consequences."},{"start_s":22.0,"text":"Athlete carries that weight into the next play."},{"start_s":26.06,"text":"Next play breaks down."},{"start_s":27.68,"text":"Spiral."},{"start_s":28.88,"text":"The mistake didn''t cost them."},{"start_s":31.66,"text":"The five seconds after did."},{"start_s":33.84,"text":"Your job in those five seconds is one thing."},{"start_s":37.18,"text":"Interruption."},{"start_s":38.42,"text":"You are not processing the mistake."},{"start_s":40.56,"text":"You are not evaluating what went wrong."},{"start_s":42.82,"text":"You have one job."},{"start_s":44.12,"text":"Get back to the next play."},{"start_s":46.24,"text":"Three steps."},{"start_s":47.54,"text":"Reset word."},{"start_s":48.84,"text":"Say it."},{"start_s":49.42,"text":"Physical cue."},{"start_s":51.0,"text":"Run it."},{"start_s":51.8,"text":"Focus anchor."},{"start_s":53.0,"text":"Return to it."},{"start_s":54.36,"text":"Five seconds."},{"start_s":55.52,"text":"Back in the game."},{"start_s":57.04,"text":"Drill that sequence three times back to back until it''s locked."},{"start_s":62.46,"text":"On your screen you are going to walk through it right now."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"A mistake just happened. 5 seconds. Step 1 — your reset word. Say it now.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Step 2 — your physical cue. Run it right now.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Step 3 — your focus anchor. Return to it. You''re here. Next play.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Again. Mistake. Reset word. Physical cue. Focus anchor.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"One more time. All three steps. Locked.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Describe what running that sequence felt like. Did it interrupt the spiral? What was hardest to execute?","min_entry_seconds":0}],"summary":{"display":"last","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_25/lesson_25_seg_02.mp3"],"total_audio_seconds":13.93,"timed_text":[{"start_s":0.0,"text":"Drill that protocol and practice this week."},{"start_s":3.56,"text":"Make an intentional error and run it."},{"start_s":6.64,"text":"Make it automatic before competition demands it."},{"start_s":10.28,"text":"After you finish, Day 25 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000025';

-- Day 26: Reframe — What You Would Do Differently (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 242,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_26/lesson_26_seg_01.mp3"],"total_audio_seconds":69.18,"timed_text":[{"start_s":0.0,"text":"Day 26."},{"start_s":2.3,"text":"We did a reframe exercise earlier in the series."},{"start_s":5.68,"text":"Today we go deeper."},{"start_s":7.54,"text":"You''ve added tools — reset word, If-Then plan, self-talk replacements."},{"start_s":15.1,"text":"Your mistake protocol, the fighter mindset, your focus anchors trained."},{"start_s":21.28,"text":"I want you to go back to a different moment."},{"start_s":23.64,"text":"One you''ve carried as a failure — where your mind got in the way."},{"start_s":31.34,"text":"We''re going to replay it."},{"start_s":33.02,"text":"Not to relive the pain, but to rewrite the response."},{"start_s":37.06,"text":"This is a specific skill."},{"start_s":39.82,"text":"You''re not pretending the bad moment didn''t happen."},{"start_s":42.74,"text":"You''re showing your nervous system: there''s a trained answer now."},{"start_s":49.72,"text":"Every time you do this, that memory loses its charge."},{"start_s":53.92,"text":"Next time it arrives, your brain looks for the trained response."},{"start_s":61.04,"text":"Think of a moment that still stings a little."},{"start_s":64.4,"text":"Yeah, that''s the one."},{"start_s":66.52,"text":"On your screen, you''re going to walk through it."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the moment — the situation, what happened, what your mind did, and how it affected your performance.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"At what exact point did the spiral begin? What was the trigger thought?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Replay it with your full toolkit. From that exact moment — walk through what you would have done. Every step. Reset word, physical cue, focus anchor, self-talk replacement. Be specific.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Read your reframed response back. This is your trained answer to that moment now.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_26/lesson_26_seg_02.mp3"],"total_audio_seconds":12.94,"timed_text":[{"start_s":0.0,"text":"That memory just became a rep. You''ve already been there with a plan."},{"start_s":7.94,"text":"Next, you''ve got a journal and after you finish, day 26 is complete."}]},{"type":"journal_prompt","prompt":"How did it feel to give your brain a trained response for that moment? Did the weight of that memory change at all?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000026';

-- Day 27: What's Next? (1 cue(s) shortened)
update public.lessons set
  duration_seconds = 166,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_27/lesson_27_seg_01.mp3"],"total_audio_seconds":77.38,"timed_text":[{"start_s":0.0,"text":"Day 27."},{"start_s":1.96,"text":"One question to carry for the rest of your career."},{"start_s":6.84,"text":"What''s next?"},{"start_s":9.0,"text":"Not what did I achieve?"},{"start_s":11.92,"text":"What''s next?"},{"start_s":13.52,"text":"Here''s why this matters."},{"start_s":15.56,"text":"One of the biggest performance killers in sport: complacency after success."},{"start_s":21.2,"text":"You make the team, hit a personal best — and your standards quietly drop."},{"start_s":30.84,"text":"Because part of your brain thinks the job is done."},{"start_s":33.96,"text":"The, what''s next habit prevents that."},{"start_s":37.08,"text":"Continuous growth — setting new limits the moment you reach the old ones."},{"start_s":48.08,"text":"Sustaining elite performance: never satisfied with what you built."},{"start_s":55.7,"text":"They used each achievement as a launching pad for the next standard."},{"start_s":62.02,"text":"Three days from completing this. Here''s the most important thing:"},{"start_s":68.36,"text":"Finishing is not the goal, the next chapter it is."},{"start_s":72.64,"text":"On your screen you''re going to answer the prompted question."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"What have you built over the last 27 days that you didn''t have when you started?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What is the next standard you''re committing to? Not a wish — a specific, behavioral commitment that starts the day after this program ends.","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What''s next? Write it as a declaration. ''After this program, I commit to...''","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_27/lesson_27_seg_02.mp3"],"total_audio_seconds":14.06,"timed_text":[{"start_s":0.0,"text":"What''s next?"},{"start_s":2.04,"text":"Keep asking that question."},{"start_s":3.84,"text":"Every achievement, every season, every milestone."},{"start_s":7.38,"text":"The answer to that question is where the growth lives."},{"start_s":10.84,"text":"Now that you''re finished, day 27 is complete."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000027';

-- Day 28: Identity Under Pressure (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 181,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_28/lesson_28_seg_01.mp3"],"total_audio_seconds":67.3,"timed_text":[{"start_s":0.0,"text":"Day 28, who are you when it gets hard?"},{"start_s":4.6,"text":"Who are you behind, two mistakes back to back, with everything on the line?"},{"start_s":20.26,"text":"Think back to where you were when this journey started."},{"start_s":23.34,"text":"There was probably a version of you with no answer for that question."},{"start_s":28.2,"text":"That defaulted to the situation."},{"start_s":30.66,"text":"That got swallowed by the moment."},{"start_s":32.84,"text":"You''ve been building the answer for 28 days."},{"start_s":36.6,"text":"The mental training doesn''t change you in the comfortable moments."},{"start_s":40.64,"text":"It reveals you in the difficult ones."},{"start_s":43.68,"text":"Every rep preparing you for that moment — the one that used to break you."},{"start_s":51.64,"text":"Today I want you to write your competition identity."},{"start_s":55.62,"text":"Not a general statement."},{"start_s":57.88,"text":"The version of you when everything is on the line and against you."},{"start_s":63.18,"text":"On your screen we''re going to take a breath and then we write."}]},{"type":"timed_exercise","duration_seconds":16,"interactive_model":"box_breathing","visual_cues":["One full cycle. Settle in.","Follow the circle."],"steps":[{"text":"Inhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"},{"text":"Exhale","duration_seconds":4,"haptic":"heavy"},{"text":"Hold","duration_seconds":4,"haptic":"light"}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Write your competition identity statement — specifically for your hardest moment. Who are you when the game is on the line, you''re behind, and everything hurts? Present tense. ''I am an athlete who...''","min_entry_seconds":0}],"summary":{"display":"last","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_28/lesson_28_seg_02.mp3"],"total_audio_seconds":13.69,"timed_text":[{"start_s":0.0,"text":"Read that before every competition from here forward."},{"start_s":3.82,"text":"Not as a wish as a reminder of a decision you''ve already made."},{"start_s":8.36,"text":"You have a journal prompt and after you finish, day 28 is complete."}]},{"type":"journal_prompt","prompt":"When was the last time you actually lived out that identity in competition? What made it possible?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000028';

-- Day 29: Reframe — Turning Adversity Into Fuel (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 189,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_29/lesson_29_seg_01.mp3"],"total_audio_seconds":75.11,"timed_text":[{"start_s":0.0,"text":"Day 29, one last reframe, and this one goes the broadest."},{"start_s":6.62,"text":"The first two reframe exercises were about specific moments."},{"start_s":10.88,"text":"A period in your career where it felt like everything was against you."},{"start_s":28.58,"text":"Most athletes carry that period as evidence against themselves."},{"start_s":33.2,"text":"That''s when I found out I wasn''t as good as I thought."},{"start_s":36.02,"text":"That''s when things started going wrong."},{"start_s":38.88,"text":"And here''s what I''ve seen working with athletes who''ve been through that."},{"start_s":41.76,"text":"They didn''t avoid the adversity — they extracted from it."},{"start_s":49.6,"text":"The hard period didn''t break them."},{"start_s":51.78,"text":"It built the part of them that''s unbreakable."},{"start_s":54.98,"text":"You cannot achieve greatness without going through the difficult parts."},{"start_s":59.28,"text":"The suffering isn''t a detour, it''s the training."},{"start_s":63.5,"text":"Your hardest stretch — not to relive it. To extract what it built."},{"start_s":70.66,"text":"On your screen, go ahead and walk through it one more time."}]},{"type":"prompt_cards","ambient_audio":"ambient/ambient_music.mp3","cards":[{"intro_hold_seconds":0,"prompt":"Describe the hardest stretch of your athletic career. What was happening? What made it difficult?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What did that period demand of you mentally that nothing else had before?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"What did you prove about yourself by getting through it — even if it didn''t feel that way at the time?","min_entry_seconds":0},{"intro_hold_seconds":0,"prompt":"Write one sentence: what that period built in you that you now compete with.","min_entry_seconds":0}],"summary":{"display":"all","header":"","hold_seconds":0}},{"type":"voiceover","audio_files":["lesson_29/lesson_29_seg_02.mp3"],"total_audio_seconds":14.35,"timed_text":[{"start_s":0.0,"text":"That adversity it wasn''t evidence against you."},{"start_s":3.36,"text":"It was the training — now in your evidence log. Not history. Ammunition."}]}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000029';

-- Day 30: The Evidence (0 cue(s) shortened)
update public.lessons set
  duration_seconds = 308,
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["lesson_30/lesson_30_seg_01.mp3"],"total_audio_seconds":86.91,"timed_text":[{"start_s":0.0,"text":"Day 30. You made it. Most people quit at Day 8 or 15 — you didn''t."},{"start_s":13.52,"text":"You kept showing up every single day."},{"start_s":16.58,"text":"That is not a small thing."},{"start_s":19.14,"text":"Think about where you were when you started this."},{"start_s":22.08,"text":"No reset word, no If-Then plan, no evidence log, no traffic light system."},{"start_s":41.16,"text":"You have all of it now."},{"start_s":42.84,"text":"Not because someone gave it to you — you built it, rep by rep, day by day."},{"start_s":50.74,"text":"The question to carry from here: What''s next?"},{"start_s":61.9,"text":"Not how much did I improve, not was it worth it, what''s next?"},{"start_s":66.6,"text":"Take it into every season, every competition, every time you plateau."},{"start_s":73.1,"text":"Before you journal one last time, I want you to do one thing."},{"start_s":76.74,"text":"Open your visualization board. Look at who you committed to becoming."}]},{"type":"program_completion","ambient_audio":"ambient/ambient_music.mp3","cards":[{"source":"profile.visualization_board","caption":"Open your visualization board. The athlete you committed to becoming on Day 23. Take your time."},{"source":"profile.evidence_log","caption":"Now your evidence log. Read it from the beginning. Not to compare — to see."},{"source":"static","text":"The distance between that board and where you stand right now? That''s the work. And you''ve already started closing it."},{"source":"static","text":"What''s next?"}]},{"type":"voiceover","audio_files":["lesson_30/lesson_30_seg_02.mp3"],"total_audio_seconds":41.78,"timed_text":[{"start_s":0.0,"text":"You don''t need a score to know what''s changed."},{"start_s":2.74,"text":"You know it in how you showed up, how you handled the last competition."},{"start_s":15.2,"text":"That''s the evidence."},{"start_s":17.0,"text":"Keep the log, run the routine, use the tools, and build on your why."},{"start_s":25.12,"text":"When it gets hard, you''ve been here before and came out with a plan."},{"start_s":35.36,"text":"That''s it."},{"start_s":36.76,"text":"Programs over, but your training isn''t."},{"start_s":39.4,"text":"Go compete like it."}]},{"type":"journal_prompt","prompt":"What is different about the way you think about competing now compared to where you started? What does the next chapter look like — and what''s your first move?"}]}'::jsonb,
  updated_at = now()
where id = 'd0000000-0000-0000-0000-000000000030';

commit;